                "compatible 4096-square panel buffers required");
    constexpr int tiles = 4096 / 64;
    constexpr int lower_tile_tasks = tiles * (tiles + 1) / 2;
    copy_panel_to_factor_kernel<<<
        lower_tile_tasks, dim3(32, 16), 0,
        c10::cuda::AC_CAT(getCurrentCUDA, AC_CAT(Str, eam))()>>>(
