                factors.size(0) * 4096 == output.size(1) &&
                factors.stride(0) == 4096 * 4096 &&
                factors.stride(1) == 1 && factors.stride(2) == 4096 &&
                output.stride(2) == 1,
                "compatible factor stack and output required");
    constexpr int tiles = 4096 / 32;
    copy_factor_lower_kernel<<<
        dim3(tiles, tiles, factors.size(0)), dim3(32, 8), 0,
        c10::cuda::AC_CAT(getCurrentCUDA, AC_CAT(Str, eam))()>>>(
            factors.data_ptr<float>(), output.data_ptr<float>(),
